-- TARGET: SubtitleDisplay gbsopnbovsxlstnmaaga. Stable IDs preserve learner history.
begin;
insert into public.englishsuccess_curriculum_meta(singleton,revision) values(true,'2026-10-19.1') on conflict(singleton) do nothing;
insert into public.englishsuccess_curriculum_sources(id,payload)
select v->>'id',v from jsonb_array_elements('[{"id":"core-inventory","title":"British Council / Eaquals Core Inventory (2011)","url":"https://www.eaquals.org/wp-content/uploads/EAQUALS_British_Council_Core_Curriculum_April2011.pdf","use":"Level-band reference. Our sequence, Thai bridges and exercises are independently authored; not a certification syllabus."},{"id":"english-profile","title":"English Grammar & Vocabulary Profile","url":"https://englishprofile.org/","use":"Detailed alignment reference; individual descriptor IDs have not yet been verified. Do not claim item-level EGP alignment."},{"id":"oxford-words","title":"Oxford 3000 / 5000","url":"https://www.oxfordlearnersdictionaries.com/wordlists/oxford3000-5000","use":"Vocabulary review reference only. No word list is copied or CEFR labels assigned to our dictionary without sense-level checking and reuse permission."},{"id":"cefr-scale","title":"Council of Europe CEFR global scale","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale","use":"Overall ability goals. Listening recognition alone does not establish speaking, pronunciation or an overall CEFR level."}]'::jsonb) v on conflict(id) do nothing;
insert into public.englishsuccess_curriculum_skills(id,level,position,payload)
select v->>'id',v->>'level',(v->>'order')::integer,v from jsonb_array_elements('[{"id":"participants","level":"A1","order":0,"title":"Who acts; who receives","family":"pronouns","thaiBridge":"Thai pronouns often retain their form across roles. English marks I/me, she/her, we/us and they/them. Test the role, not the gender.","prerequisites":[],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"be-forms","level":"A1","order":1,"title":"Matching be to the subject","family":"verbs","thaiBridge":"Thai descriptions may not require an equivalent of be. English requires am/is/are with these subjects.","prerequisites":["participants"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"reference","level":"A1","order":2,"title":"One, several, this, that","family":"determiners","thaiBridge":"Thai does not have an article system equivalent to English. Use a clear referent and number; do not translate the as a fixed Thai word.","prerequisites":[],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"ownership","level":"A1","order":3,"title":"Owner and possession","family":"pronouns","thaiBridge":"Thai can use khong + owner. English distinguishes my/mine and her/hers by their place in the phrase.","prerequisites":["participants","reference"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"routine-now","level":"A1","order":4,"title":"Routine versus happening now","family":"verbs","thaiBridge":"Gam lang can signal an ongoing event. Contrast an English routine with be + -ing while keeping the action identical.","prerequisites":["be-forms"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"past-state","level":"A1","order":5,"title":"Current and earlier states","family":"verbs","thaiBridge":"Thai uses context and time expressions; English changes is/are to was/were.","prerequisites":["be-forms"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"negation","level":"A1","order":6,"title":"Positive and negative","family":"verbs","thaiBridge":"Mai does not map to one fixed English form. Contrast not with be and do-support with lexical verbs.","prerequisites":["be-forms"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"questions","level":"A1","order":7,"title":"Asking and answering","family":"verbs","thaiBridge":"Thai question particles do not move the verb. English may need be inversion or do/does before the subject.","prerequisites":["be-forms","negation"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"time-place","level":"A1","order":8,"title":"Location and time relations","family":"relationships","thaiBridge":"Thai relational words do not map one-to-one to English prepositions. Keep locations and events constant between choices.","prerequisites":[],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"simple-links","level":"A1","order":9,"title":"Add, contrast, explain","family":"relationships","thaiBridge":"Lae, tae and phro help introduce the meaning of and, but and because. Both choices must not be equally defensible.","prerequisites":["negation"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"past-events","level":"A1","order":10,"title":"Finished events","family":"verbs","thaiBridge":"Laew is not a universal past-tense marker. Contrast a finished event with a routine, using the same action.","prerequisites":["routine-now"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"request-basics","level":"A1","order":11,"title":"Ask politely; give directions","family":"interaction","thaiBridge":"English requests rely on modal and sentence choices, not an equivalent of khrap/kha appended to every sentence.","prerequisites":["questions"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"future","level":"A2","order":12,"title":"Plans and upcoming actions","family":"verbs","thaiBridge":"Ja introduces future or intended events in many contexts. English distinguishes will, going to and present arrangements.","prerequisites":["routine-now"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"completion","level":"A2","order":13,"title":"In progress versus completed","family":"verbs","thaiBridge":"Gam lang and laew provide a starting contrast, not a complete equivalence to continuous and perfect forms.","prerequisites":["routine-now","past-events"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"verb-shapes","level":"A2","order":14,"title":"Verb forms after helpers","family":"verbs","thaiBridge":"English auxiliaries determine the following verb form; Thai verbs do not take these same endings.","prerequisites":["completion","questions"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"obligation","level":"A2","order":15,"title":"Ability, permission, obligation","family":"verbs","thaiBridge":"Dai and tong can help establish the distinction, but cannot be substituted mechanically for every can or must.","prerequisites":["negation"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"verb-complements","level":"A2","order":16,"title":"What follows a verb","family":"verbs","thaiBridge":"Learn whole patterns such as ask someone to wait and want to leave; not an isolated translation of to.","prerequisites":["participants","verb-shapes"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"quantity","level":"A2","order":17,"title":"Amounts and countability","family":"determiners","thaiBridge":"Thai classifiers and English articles/countability divide the work differently. Use the same object and clear quantity evidence.","prerequisites":["reference"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"sequence","level":"A2","order":18,"title":"Order events and conditions","family":"relationships","thaiBridge":"Use Thai to disambiguate before, after and if while holding the events stable.","prerequisites":["time-place","past-events"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"comparison","level":"A2","order":19,"title":"Compare choices","family":"relationships","thaiBridge":"Kwa helps introduce comparison. English also changes adjectives or uses more; test the relation, not different objects.","prerequisites":["reference"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"repair","level":"B1","order":20,"title":"Clarify a misunderstanding","family":"interaction","thaiBridge":"Practise checking the intended meaning rather than choosing a response by a recognised noun.","prerequisites":["request-basics","questions"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"past-sequence","level":"B1","order":21,"title":"Earlier than another past event","family":"verbs","thaiBridge":"Explicit Thai event order supports English past-perfect contrasts without pretending laew alone identifies the tense.","prerequisites":["completion","sequence"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"passive","level":"B1","order":22,"title":"Action and affected person","family":"verbs","thaiBridge":"Thai thuk/dai rap may help in some contexts. English passive changes focus and requires be plus a participle.","prerequisites":["participants","verb-shapes"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"possibility","level":"B1","order":23,"title":"Certainty and possibility","family":"verbs","thaiBridge":"Thai uncertainty expressions support the meaning; English modals and their forms distinguish confidence and time.","prerequisites":["obligation","future"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"reported","level":"B1","order":24,"title":"Report someone’s message","family":"verbs","thaiBridge":"Keep the speaker and event fixed while testing English changes in reference and reported time.","prerequisites":["past-sequence","participants"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"hypothetical","level":"B1","order":25,"title":"Imagine a different situation","family":"relationships","thaiBridge":"Thai tha does not require the same English tense pattern in hypothetical conditions.","prerequisites":["sequence","past-events"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"relative","level":"B2","order":26,"title":"Identify which person or thing","family":"relationships","thaiBridge":"Thai thi is a bridge to some relative clauses, not a one-to-one translation of who, which and that.","prerequisites":["participants","reference"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"future-completion","level":"B2","order":27,"title":"Completed by a future point","family":"verbs","thaiBridge":"Hold the deadline and action constant; test whether English describes progress or completion at that point.","prerequisites":["completion","future"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"counterfactual","level":"B2","order":28,"title":"Unreal causes and consequences","family":"relationships","thaiBridge":"Keep the event facts explicit in Thai; test the relationship between a different past and its consequences.","prerequisites":["hypothetical","past-sequence"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"qualification","level":"B2","order":29,"title":"Qualify and contrast ideas","family":"relationships","thaiBridge":"Understand a concession or exception, not just the nearest familiar word in a longer sentence.","prerequisites":["simple-links","relative"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"professional-response","level":"B2","order":30,"title":"Handle an unexpected problem","family":"interaction","thaiBridge":"Choose by obligation, intention and politeness while keeping the guest’s problem identical.","prerequisites":["repair","possibility"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"nuance","level":"C1","order":31,"title":"Implication and degrees of commitment","family":"interaction","thaiBridge":"The options should differ in intended implication or commitment, not in who or what is mentioned.","prerequisites":["professional-response","qualification"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (C1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"focus","level":"C1","order":32,"title":"Shift emphasis and information focus","family":"relationships","thaiBridge":"Thai and English can highlight information differently. Test what is foregrounded without swapping the event.","prerequisites":["relative","passive"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (C1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]},{"id":"complex-time","level":"C1","order":33,"title":"Combine time and viewpoint","family":"verbs","thaiBridge":"Distinguish the speaker’s viewpoint across several events instead of assigning a single English tense to laew.","prerequisites":["future-completion","counterfactual"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (C1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}]}]'::jsonb) v on conflict(id) do nothing;
insert into public.englishsuccess_course_skills(course,skill,node_id,position)
select v->>'course',v->>'skill',v->>'nodeId',(v->>'order')::integer from jsonb_array_elements('[{"course":"hotel","skill":"roles","nodeId":"participants","order":0},{"course":"hotel","skill":"object_forms","nodeId":"participants","order":1},{"course":"hotel","skill":"be_agreement","nodeId":"be-forms","order":2},{"course":"hotel","skill":"articles","nodeId":"reference","order":3},{"course":"hotel","skill":"possessive_forms","nodeId":"ownership","order":4},{"course":"hotel","skill":"habit_ongoing","nodeId":"routine-now","order":5},{"course":"hotel","skill":"past_states","nodeId":"past-state","order":6},{"course":"hotel","skill":"negative","nodeId":"negation","order":7},{"course":"hotel","skill":"do_support","nodeId":"questions","order":8},{"course":"hotel","skill":"prepositions","nodeId":"time-place","order":9},{"course":"hotel","skill":"future_ongoing","nodeId":"future","order":10},{"course":"hotel","skill":"ongoing_finished","nodeId":"completion","order":11},{"course":"hotel","skill":"verb_forms","nodeId":"verb-shapes","order":12},{"course":"hotel","skill":"modal_meaning","nodeId":"obligation","order":13},{"course":"hotel","skill":"verb_patterns","nodeId":"verb-complements","order":14},{"course":"hotel","skill":"passive","nodeId":"passive","order":15}]'::jsonb) v on conflict(course,skill) do nothing;
insert into public.englishsuccess_course_questions(id,course,skill,position,payload)
